<?php
$listing=$listing??['rows'=>[],'page'=>1,'page_count'=>1,'filter'=>'all','total'=>0];$filters=['all'=>'All','unread'=>'Unread','trading'=>'Trading','funds'=>'Funds','verification'=>'Verification','support'=>'Support','system'=>'System'];
$pageUrl=static function(int $page)use($listing):string{return \client_url('notifications').'?'.http_build_query(['filter'=>$listing['filter'],'page'=>$page]);};
?>
<section class="client-page-intro"><div><span class="client-eyebrow">ACCOUNT ACTIVITY</span><h1>Notifications</h1><p>Recent account, demo trading, verification, funds, and support updates.</p></div><span class="comm-unread-summary" data-unread-summary><?=e((string)$unreadCount)?> unread</span></section>
<section class="comm-panel client-panel">
 <div class="comm-toolbar"><nav class="comm-filters" aria-label="Notification filters"><?php foreach($filters as $key=>$label): ?><a class="<?=($listing['filter']===$key?'is-active':'')?>" href="<?=e(\client_url('notifications').'?'.http_build_query(['filter'=>$key]))?>" <?=($listing['filter']===$key?'aria-current="page"':'')?>><?=e($label)?></a><?php endforeach; ?></nav><?php if($unreadCount>0): ?><form action="<?=e(\site_url('api/notifications/read-all'))?>" method="post" data-mark-all><?=\csrf_field()?><button class="client-button client-button-quiet" type="submit">Mark all as read</button></form><?php endif; ?></div>
 <?php if($listing['rows']===[]): ?><div class="comm-empty"><span aria-hidden="true">◷</span><strong>No notifications in this view</strong><p>Account updates will appear here when they happen.</p></div><?php else: ?><ul class="notification-list"><?php foreach($listing['rows'] as $row): ?><li class="notification-item <?=empty($row['is_read'])?'is-unread':''?>" data-notification-id="<?=e((string)$row['id'])?>"><span class="notification-icon" aria-hidden="true"><?=match($row['category']){'Trading'=>'↗','Funds'=>'$','Verification'=>'✓','Support'=>'?','Account'=>'◎',default=>'•'}?></span><div class="notification-copy"><div class="notification-heading"><span class="notification-category"><?=e($row['category'])?></span><?php if(empty($row['is_read'])):?><span class="notification-unread-label">Unread</span><?php endif;?></div><strong><?=e($row['title'])?></strong><p><?=e($row['message'])?></p><time datetime="<?=e(date(DATE_ATOM,strtotime($row['created_at'])))?>"><?=e(\App\Services\DashboardService::formatDate($row['created_at']))?></time></div><div class="notification-actions"><?php if(!empty($row['safe_link'])):?><a class="client-text-link" href="<?=e($row['safe_link'])?>"><?=e($row['category']==='Support'?'Open ticket':'View details')?> →</a><?php endif;?><?php if(empty($row['is_read'])):?><form action="<?=e(\site_url('api/notifications/'.$row['id'].'/read'))?>" method="post" data-mark-read><?=\csrf_field()?><button class="client-button client-button-quiet" type="submit">Mark as read</button></form><?php endif;?></div></li><?php endforeach;?></ul><nav class="client-pagination" aria-label="Notification pages"><a href="<?=e($pageUrl(max(1,$listing['page']-1)))?>" aria-disabled="<?=$listing['page']<=1?'true':'false'?>">← Previous</a><span>Page <?=e((string)$listing['page'])?> of <?=e((string)$listing['page_count'])?> · <?=e((string)$listing['total'])?> notifications</span><a href="<?=e($pageUrl(min($listing['page_count'],$listing['page']+1)))?>" aria-disabled="<?=$listing['page']>=$listing['page_count']?'true':'false'?>">Next →</a></nav><?php endif;?>
 <div class="comm-live-status" data-comm-status role="status" aria-live="polite"></div>
</section>
